    # Normalise input to a string of characters
    if isinstance(s, str):
        seq = s
    elif isinstance(s, (bytes, bytearray)):
        try:
            seq = s.decode()
        except Exception:
            # Fallback: convert each byte to a character via chr
            seq = ''.join(chr(b) for b in s)
    else:
        try:
            seq = ''.join(str(ch) for ch in s)
        except Exception:
            # Not iterable – treat as empty
            seq = ''
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in seq:
        if ch in opening:
